const files = ["app/(help)/help/[category]/[slug]/page.tsx", "app/(help)/help/[category]/page.tsx", "app/(help)/help/changelog/page.tsx"]
const bad = []
for (const f of files) {
  if (!fs.existsSync(f)) { console.error("SCAN-804: " + f + " is missing"); process.exit(79) }
  const s = fs.readFileSync(f, "utf8")
  const m = /title:\s*[`"][^`"\n]*\| Help[`"]/.exec(s)
  if (m) bad.push(f)
}
if (bad.length) { console.error("SCAN-804: " + bad.join(", ") + " still set the document title with a pipe (| Help), so under the root template every help page reads like Streaks | Help · Frequency, two separators, and disagrees with its own OG title."); process.exit(1) }
'
